    /// Test fixture: the factory mints to an account that is already registered.
    pub fn mint(&mut self, account_id: AccountId, amount: U128) {
        require!(Self::is_factory(&env::predecessor_account_id()), "Only the factory account can mint");
        self.token.internal_deposit(&account_id, amount.into());
        near_contract_standards::fungible_token::events::FtMint {
            owner_id: &account_id,
            amount,
            memo: None,
        }
        .emit();
    }

    fn is_factory(caller: &AccountId) -> bool {
        let me = env::current_account_id();
        match me.as_str().split_once('.') {
            Some((_, parent)) => caller.as_str() == parent,
            None => false,
        }
